INSERT INTO subject_fix VALUES
('fc398322-968c-44cb-b9fa-cbcf9bf81d2f'::uuid,'عودة الطائر',2,'cd3a849d-db92-4c7c-8288-91a5a129f676'::uuid,1392,25,'https://elearn.azureedge.net/Books/c2/ar2-p1.pdf',$subject0$[ضاديوم — مطابقة مضمون درس «عودة الطائر» مع الكتاب الفلسطيني الفعلي]
المصدر: كتاب «لغتنا الجميلة» الصف الثاني، الجزء الأول، الصفحة المطبوعة 25 وما بعدها، النسخة المتاحة من بوابة التعليم الفلسطينية: https://elearn.azureedge.net/Books/c2/ar2-p1.pdf. هذه النسخة هي الطبعة الرابعة المطبوعة عام 2020؛ لا يوجد هنا دليل على أنها آخر نسخة معدلة للعام الدراسي 2026–2027.
هذا شرح أصلي من ضاديوم لأحداث الدرس ومهاراته، وليس نقلًا لنص الكتاب الحكومي، ولا ينبغي استبدال قصته بقصة إثرائية غير مطابقة.

أولًا: أتعرّف موضوع الدرس الحقيقي
بدأت العصافير تطير مسرورة، ثم هبّت عاصفة شديدة ونزل مطر غزير؛ فاختبأت العصافير. سقط عصفور صغير بعد أن تناثر ريشه، ولم يعد يستطيع الطيران. اجتمعت العصافير، ومنح كل واحد منها ريشة من ريشه حتى صار للعصفور الصغير ما يعينه على الطيران، فعاد إلى عشه سالمًا بصحبة أصدقائه.

ثانيًا: أفهم الفكرة والأسباب والنتائج
القضية الرئيسة تعاون جماعة العصافير على مساعدة صغير ضعيف؛ فالنجاة لم تتحقق من تبدل الطقس وحده، بل بتكاتف الأصدقاء.
أحدد الحدث الأول ثم المشكلة أو الحاجة التي واجهتها الشخصيات، وأميز السبب والنتيجة. أستشهد بتفصيل ورد في شرح مضمون الكتاب دون إضافة أسماء أو أحداث غير موجودة فيه. أستطيع أن أرتب الأفكار في ثلاث جمل، ثم أشرح لماذا انتهت القصة على هذا النحو.

ثالثًا: أكتسب المفردات وأستعملها
العاصفة: ريح قوية قد يصحبها المطر؛ تناثر: تفرق؛ الريشة: ما يغطي جسم الطائر؛ عَشّ: موضع تعيش فيه طيور؛ اجتمع: أصبحوا معًا.
أختار مفردتين وأضع كل واحدة في جملة من إنشائي. أبحث في السياق عن الجملة التي تساعدني على فهم المعنى وأقارن بين المعنى داخل الدرس ومعنى الكلمة في موقف آخر، بحسب مستواي في القراءة.

رابعًا: أتعلّم الموضوع اللغوي المرتبط بالنص
من تدريبات صفحات الدرس أميز الدال والذال في النطق والكتابة، وأجرد حرف الراء من الكلمات، وأبحث عن الزاي داخل كلمات مناسبة، ثم أقرأ كلمات فيها هذه الحروف دون الخلط بين نقاطها.
أقرأ مثالًا بصوت واضح ثم أكتبه بخط مناسب للصف. ألاحظ تغير الحروف أو الحركات في الكلمة وأراجع إملاءها مع المعلم. هذا الجزء تدريب ضاديوم أصلي على المهارة التي يتناولها الكتاب ولا يحل محل أمثلته الأصلية.

خامسًا: أفكر وأعبّر عن فهمي
ما الذي غيّر الجو فجأة؟ لماذا لم يقدر الصغير على الطيران؟ كيف ساهمت بقية العصافير في مساعدته؟ إلى أين عاد في النهاية؟
أجيب في جمل تامة، وأوضح كيف عرفت الإجابة من الحدث نفسه. أكتب ملخصًا قصيرًا يذكر الشخصيات وتسلسل الأحداث والفكرة الرئيسة. أنسب القصة الوزارية إلى صاحبها كما في الكتاب إذا كان معروفًا، وأتعامل مع النص الإثرائي القديم بصفته تدريبًا إضافيًا مستقلًا لا مصدرًا للإجابات.

[نهاية شرح موضوع الدرس المطابق لأحداث الكتاب]$subject0$,'["أن يرتب الطالب ثلاثة أحداث أصلية من قصة «عودة الطائر» ويميّز سبب المشكلة ونتيجتها.","أن يفسر الطالب مفردتين مرتبطتين بالموضوع ويستشهد بتفصيل يدعم الإجابة.","أن يوظف الطالب مهارة لغوية من درس «عودة الطائر» في جملة مكتوبة وملخص قصير."]'::jsonb),
('899565c6-d9cb-4ab4-ae75-7ce6160599b9'::uuid,'الغراب والجرة',2,'cd3a849d-db92-4c7c-8288-91a5a129f676'::uuid,1439,45,'https://elearn.azureedge.net/Books/c2/ar2-p1.pdf',$subject1$[ضاديوم — مطابقة مضمون درس «الغراب والجرة» مع الكتاب الفلسطيني الفعلي]
المصدر: كتاب «لغتنا الجميلة» الصف الثاني، الجزء الأول، الصفحة المطبوعة 45 وما بعدها، النسخة المتاحة من بوابة التعليم الفلسطينية: https://elearn.azureedge.net/Books/c2/ar2-p1.pdf. هذه النسخة هي الطبعة الرابعة المطبوعة عام 2020؛ لا يوجد هنا دليل على أنها آخر نسخة معدلة للعام الدراسي 2026–2027.
هذا شرح أصلي من ضاديوم لأحداث الدرس ومهاراته، وليس نقلًا لنص الكتاب الحكومي، ولا ينبغي استبدال قصته بقصة إثرائية غير مطابقة.

أولًا: أتعرّف موضوع الدرس الحقيقي
في يوم صيفي حار عطش غراب كثيرًا، فبحث عن ماء حتى عثر على جرّة فيها كمية من الماء لا يصل إليها بمنقاره. فكّر في حلّ، ثم جمع أحجارًا صغيرة وألقى بها داخل الجرّة. ارتفع مستوى الماء تدريجيًا حتى استطاع الشرب. لم يكن الحل مجرد محاولة الوصول بعنقه؛ بل تغيير مستوى الماء بإضافة الحجارة.

ثانيًا: أفهم الفكرة والأسباب والنتائج
تدور القصة حول حل المشكلات بالتفكير والتجربة وعدم الاستسلام، وتربط ذلك بقيمة الماء وترشيد استخدامه.
أحدد الحدث الأول ثم المشكلة أو الحاجة التي واجهتها الشخصيات، وأميز السبب والنتيجة. أستشهد بتفصيل ورد في شرح مضمون الكتاب دون إضافة أسماء أو أحداث غير موجودة فيه. أستطيع أن أرتب الأفكار في ثلاث جمل، ثم أشرح لماذا انتهت القصة على هذا النحو.

ثالثًا: أكتسب المفردات وأستعملها
الجرّة: إناء يوضع فيه السائل؛ المنقار: فم الطائر الصلب؛ عطش: احتاج إلى ماء؛ مستوى: ارتفاع سطح الماء؛ تدبّر: فكّر بهدوء.
أختار مفردتين وأضع كل واحدة في جملة من إنشائي. أبحث في السياق عن الجملة التي تساعدني على فهم المعنى وأقارن بين المعنى داخل الدرس ومعنى الكلمة في موقف آخر، بحسب مستواي في القراءة.

رابعًا: أتعلّم الموضوع اللغوي المرتبط بالنص
أراجع حرفي الطاء والظاء، وأميز موضع النقطة في الظاء، ثم أفرق بين حرفي العين والغين في كلمات مثل «عطش» و«غراب». أوضح أن سبب ارتفاع الماء هنا إزاحة الحجارة جزءًا من حيز الجرّة؛ وهو تفسير مبسط لما لاحظه الغراب.
أقرأ مثالًا بصوت واضح ثم أكتبه بخط مناسب للصف. ألاحظ تغير الحروف أو الحركات في الكلمة وأراجع إملاءها مع المعلم. هذا الجزء تدريب ضاديوم أصلي على المهارة التي يتناولها الكتاب ولا يحل محل أمثلته الأصلية.

خامسًا: أفكر وأعبّر عن فهمي
أين وجد الغراب الماء؟ لماذا لم يصل إليه أولًا؟ ما المواد التي وضعها في الجرّة؟ ماذا تغير بعد وضعها؟ كيف نحافظ على الماء؟
أجيب في جمل تامة، وأوضح كيف عرفت الإجابة من الحدث نفسه. أكتب ملخصًا قصيرًا يذكر الشخصيات وتسلسل الأحداث والفكرة الرئيسة. أنسب القصة الوزارية إلى صاحبها كما في الكتاب إذا كان معروفًا، وأتعامل مع النص الإثرائي القديم بصفته تدريبًا إضافيًا مستقلًا لا مصدرًا للإجابات.

